media.css:
[data-ui-unit="media"].product-media {
  margin: 0;
  width: 100%;
  aspect-ratio: 1 / 1;
}

[data-ui-unit="media"].product-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 44% center;
  display: block;
}

identity.css:
[data-ui-unit="identity"].product-identity .eyebrow {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: var(--title-gap);
}

[data-ui-unit="identity"].product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  color: var(--text-primary);
  word-break: keep-all;
  overflow-wrap: break-word;
}

[data-ui-unit="identity"].product-identity .price-row {
  margin-top: var(--price-gap);
}

[data-ui-unit="identity"].product-identity .price {
  font-size: 24px;
  font-weight: 800;
  color: var(--text-primary);
}

[data-ui-unit="identity"].product-identity .metadata {
  display: flex;
  flex-wrap: wrap;
  gap: var(--metadata-gap);
  margin-top: 24px;
}

[data-ui-unit="identity"].product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: var(--icon-label-gap);
}

[data-ui-unit="identity"].product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
  object-fit: contain;
  color: var(--text-secondary);
}

[data-ui-unit="identity"].product-identity .meta-item span {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
}

[data-ui-unit="identity"].product-identity .description {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.75;
  color: var(--text-primary);
  margin-top: var(--content-gap);
  word-break: keep-all;
  overflow-wrap: break-word;
}

booking.css:
[data-ui-unit="booking"]#booking-layout {
  display: flex;
  flex-direction: column;
}


[data-ui-unit="booking"] .booking-host-title {
  font-size: 18px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--text-primary);
  margin-top: 8px;
}

[data-ui-unit="booking"] .booking-host-subtitle {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-top: 4px;
}


[data-ui-unit="booking"] #booking-actions {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
}


[data-ui-unit="booking"] .booking-icon-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f2f2f5;
  border-radius: 8px;
  border: none;
  padding: 0;
  cursor: pointer;
  transition: background-color 0.1s ease;
}

[data-ui-unit="booking"] .booking-icon-btn img {
  width: 24px;
  height: 24px;
  display: block;
  object-fit: contain;
  color: var(--text-primary);
}

[data-ui-unit="booking"] .booking-icon-btn[aria-pressed="true"] {
  background-color: #e6e1ff;
}

[data-ui-unit="booking"] .booking-icon-btn[aria-pressed="true"] img {
  color: var(--action-bg);
}

[data-ui-unit="booking"] .booking-icon-btn:active {
  transform: scale(0.96);
}


[data-ui-unit="booking"] .booking-primary-btn {
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--action-bg);
  color: var(--action-fg);
  border: none;
  border-radius: 6px;
  padding-block: var(--action-pad-block);
  padding-inline: var(--action-pad-inline);
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  white-space: normal;
  width: 0; 
  min-width: 0;
  overflow-wrap: break-word;
  text-align: center;
}


[data-ui-unit="booking"] .booking-note {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-top: 12px;
  text-align: center;
}
